from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    def extract_groups(paren_string):
        groups = []
        group = ""
        in_group = False
        for char in paren_string:
            if char == '(':
                in_group = True
            if in_group:
                group += char
            if char == ')':
                in_group = False
                groups.append(group)
                group = ""
        return groups

    def remove_spaces(groups):
        return [group.replace(" ", "") for group in groups]

    def is_balanced(group):
        stack = []
        for char in group:
            if char == '(':
                stack.append(char)
            elif char == ')':
                if not stack:
                    return False
                stack.pop()
        return not stack

    groups = extract_groups(paren_string)
    groups = remove_spaces(groups)
    balanced_groups = [group for group in groups if is_balanced(group)]

    return balanced_groups

